import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = -1;
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (!line.isEmpty()) {
                StringTokenizer st = new StringTokenizer(line);
                n = Integer.parseInt(st.nextToken());
                break;
            }
        }

        StringBuilder sb = new StringBuilder();

        if (n == 1) {
            sb.append(1).append('\n');
        } else if (n == 2) {
            sb.append(-1).append('\n');
        } else if ((n & 1) == 1) {
            // N ímpar: preencher com 1..N^2 em ordem.
            // Média da linha i é o elemento central da linha; média da coluna j
            // é o elemento central da coluna. Ambos presentes.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (j > 0) sb.append(' ');
                    sb.append(i * n + j + 1);
                }
                sb.append('\n');
            }
        } else {
            // N par (N >= 4): N = 2k
            // Linha i: parcelas b0*s_i + t_j, onde t = {1..N-1, 3k} (média t = k+1, presente na linha)
            // e s = {0..N-2, 3k-1} com média k (presente nas colunas, na linha k+1).
            // Todas as N^2 parcelas são distintas porque b0 = 3k > máx diferença de t = 3k-1.
            long k = n / 2;
            long b0 = 3 * k;
            for (int i = 0; i < n; i++) {
                long s = (i < n - 1) ? i : (3 * k - 1);
                for (int j = 0; j < n; j++) {
                    long t = (j < n - 1) ? (j + 1) : (3 * k);
                    if (j > 0) sb.append(' ');
                    sb.append(b0 * s + t);
                }
                sb.append('\n');
            }
        }

        System.out.print(sb);
    }
}
